 public static partial class SelfTests {
  sealed class ConfirmationFake:ISefaz,IConfirmationSefaz {
   public int Sent,Queries,Sciences;public bool Fail;public Action BeforeConfirm;
   public List<string> Keys=new List<string>();public Queue<byte[]> Replies=new Queue<byte[]>(),Docs=new Queue<byte[]>();
   public byte[] Confirm(string c,int e,string key,CancellationToken token){token.ThrowIfCancellationRequested();if(BeforeConfirm!=null)BeforeConfirm();Sent++;Keys.Add(key);if(Fail)throw new IOException("Resposta da confirmação perdida");return Replies.Count>0?Replies.Dequeue():ScienceReply(key,type:"210200");}
   public byte[] Science(string c,int e,string k,CancellationToken t){Sciences++;throw new Exception("Ciência não deveria ser enviada neste fluxo");}
   public byte[] Distribute(string c,int u,int e,string n,string k,CancellationToken token){token.ThrowIfCancellationRequested();Queries++;return Docs.Dequeue();}
  }
  static byte[] ManifestationEvent(int number,string type){XNamespace n=Rules.NfeNs;return Rules.Utf8(new XDocument(new XElement(n+"procEventoNFe",new XElement(n+"evento",new XElement(n+"infEvento",new XElement(n+"CNPJ",SampleCnpj),new XElement(n+"chNFe",ReceivedKey(number)),new XElement(n+"tpEvento",type),new XElement(n+"dhEvento","2026-10-13T12:00:00-03:00"))),new XElement(n+"retEvento",new XElement(n+"infEvento",new XElement(n+"tpAmb","1"),new XElement(n+"cStat","135"),new XElement(n+"chNFe",ReceivedKey(number)),new XElement(n+"tpEvento",type),new XElement(n+"nSeqEvento","1"),new XElement(n+"nProt","123456789012345"))))));}
  static byte[] InvoiceWithProducts(int number){XNamespace n=Rules.NfeNs;var x=Rules.Xml(ReceivedInvoice(number));x.Descendants(n+"total").Single().AddBeforeSelf(new XElement(n+"det",new XAttribute("nItem",1),new XElement(n+"prod",new XElement(n+"cProd","TESTE-1"),new XElement(n+"xProd","PRODUTO FICTICIO"),new XElement(n+"qCom","1.0000"))));return Rules.Utf8(x);}
  static void TestConfirmation(string root){
   var lib=new XmlLibrary(Path.Combine(root,"confirm-lib"),SampleCnpj,1);lib.Store(ReceivedSummary(500),"1");lib.Store(ReceivedSummary(501),"2");lib.Store(ReceivedSummary(502),"3");lib.Store(ManifestationEvent(500,"210210"),"4");
   var states=new StateStore(Path.Combine(root,"confirm-state"));var queues=new KeyQueueStore(Path.Combine(root,"confirm-q"));var history=new ConfirmationStore(Path.Combine(root,"confirm-history"));var fake=new ConfirmationFake();var q=new KeyQueue{Uf=35,DownloadAll=true,AutoContinue=true};q.Add(new[]{ReceivedKey(500),ReceivedKey(502)});queues.Save(SampleCnpj,1,q);var runner=new AutoConfirmationRunner(states,history,queues,lib,fake,null);
   Check(!runner.HasPendingWork()&&runner.Run(CancellationToken.None)==0&&fake.Sent==0,"confirmação não começa com autorização antiga de ciência");q.ConfirmForDownload=true;queues.Save(SampleCnpj,1,q);Check(runner.Run(CancellationToken.None)==0,"confirmação requer autorização própria registrada");q.ConfirmationConsent=DateTime.UtcNow;queues.Save(SampleCnpj,1,q);Check(runner.Run(CancellationToken.None)==0,"chaves de tarefas internas não são confirmadas");Check(q.AddUserKeys(new[]{ReceivedKey(500)})==0&&q.Jobs[0].UserSupplied&&!q.Jobs[1].UserSupplied,"colar chave existente marca somente aquela como fornecida pelo usuário");q.Jobs[0].ScienceCode="596";q.Jobs[0].Attempts=1;q.Jobs[0].Code="138";queues.Save(SampleCnpj,1,q);
   var persisted=queues.Load(SampleCnpj,1);Check(persisted.ConfirmForDownload&&persisted.ConfirmationConsent!=DateTime.MinValue&&persisted.Jobs[0].UserSupplied&&!persisted.Jobs[1].UserSupplied,"autorização e origem manual persistem por chave");Check(!queues.Load(SampleCnpj,2).ConfirmForDownload,"homologação não herda confirmação de produção");
   bool beforeSend=false;fake.BeforeConfirm=()=>beforeSend=history.Load(SampleCnpj,1).Records.Single().Status=="Incerta";
   Check(runner.HasPendingWork()&&runner.Run(CancellationToken.None)==1&&fake.Sent==1&&fake.Keys.Single()==ReceivedKey(500)&&fake.Sciences==0,"confirma apenas a chave colada, inclusive com ciência 596 ou ciência anterior");Check(beforeSend,"tentativa de confirmação é durável antes da transmissão");var record=history.Load(SampleCnpj,1).Records.Single();Check(record.Registered&&record.Code=="135"&&record.Protocol!=""&&record.Queued,"protocolo da confirmação é persistido antes do agendamento");Check(File.Exists(record.ResponsePath)&&File.ReadAllBytes(record.ResponsePath).SequenceEqual(ScienceReply(ReceivedKey(500),type:"210200")),"retorno original da confirmação preservado");q=queues.Load(SampleCnpj,1);Check(q.Jobs[0].ConfirmationCode=="135"&&q.Jobs[0].ScienceCode=="596"&&q.Jobs[0].AwaitXml&&q.Jobs[0].NotBefore>DateTime.UtcNow.AddMinutes(4),"códigos de ciência e confirmação permanecem separados e XML fica agendado");Check(!runner.HasPendingWork()&&runner.Run(CancellationToken.None)==0&&fake.Sent==1,"reabrir não repete confirmação nem ocupa o timer sem trabalho");
   q.Jobs[1].NotBefore=DateTime.UtcNow.AddHours(1);queues.Save(SampleCnpj,1,q);new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);Check(fake.Queries==0,"não consulta XML antes da espera após confirmação");q=queues.Load(SampleCnpj,1);q.Jobs[0].NotBefore=DateTime.UtcNow.AddMinutes(-1);queues.Save(SampleCnpj,1,q);fake.Docs.Enqueue(Response("138","1","1",ReceivedSummary(500)));new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);Check(queues.Load(SampleCnpj,1).Jobs[0].Status=="Pendente"&&queues.Load(SampleCnpj,1).Jobs[0].Message.StartsWith("Confirmação 135"),"resumo depois da confirmação mantém espera sem alegar XML completo");q=queues.Load(SampleCnpj,1);q.Jobs[0].NotBefore=DateTime.UtcNow.AddMinutes(-1);queues.Save(SampleCnpj,1,q);fake.Docs.Enqueue(Response("138","1","1",InvoiceWithProducts(500)));new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);var complete=lib.List().Single(d=>d.Key==ReceivedKey(500)&&d.Category=="Recebidas");XNamespace n=Rules.NfeNs;Check(queues.Load(SampleCnpj,1).Jobs[0].Status=="Baixada"&&Rules.Xml(File.ReadAllBytes(complete.FilePath)).Descendants(n+"xProd").Single().Value=="PRODUTO FICTICIO","XML liberado com produtos é salvo integralmente em Recebidas");Check(states.Load(SampleCnpj,1).Last==Rules.Nsu("0"),"confirmação e consulta pontual preservam NSU sequencial");
   Check(AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(500),type:"210200",code:"136"),SampleCnpj,1,ReceivedKey(500)).Status=="Sem vínculo","136 de confirmação é distinguido de vínculo aceito");Check(AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(500),type:"210200",code:"573"),SampleCnpj,1,ReceivedKey(500)).Registered,"duplicidade de confirmação conferida permite consultar XML");Reject(()=>AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(500)),SampleCnpj,1,ReceivedKey(500)),"resposta de ciência não serve como confirmação");Reject(()=>AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(501),type:"210200"),SampleCnpj,1,ReceivedKey(500)),"confirmação de outra chave é rejeitada");Reject(()=>AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(500),type:"210200",env:2),SampleCnpj,1,ReceivedKey(500)),"confirmação de outro ambiente é rejeitada");Reject(()=>AutoConfirmationRunner.Parse(ScienceReply(ReceivedKey(500),type:"210200",recipient:"12345678000195"),SampleCnpj,1,ReceivedKey(500)),"confirmação confere empresa do retorno");var bad=Rules.Xml(ScienceReply(ReceivedKey(500),type:"210200"));bad.Descendants(n+"nSeqEvento").Single().Value="2";Reject(()=>AutoConfirmationRunner.Parse(Rules.Utf8(bad),SampleCnpj,1,ReceivedKey(500)),"confirmação não assume sequência de retificação");
   foreach(string type in new[]{"110111","210220","210240"})Check(!AutoConfirmationRunner.Eligible(lib.Describe(ReceivedSummary(501)),SampleCnpj,new[]{new DocItem{Key=ReceivedKey(501),Category="Eventos",EventType=type}}),"confirmação não substitui evento incompatível "+type);Check(!AutoConfirmationRunner.Eligible(lib.Describe(ReceivedSummary(501,"3")),SampleCnpj,lib.List()),"não confirma resumo cancelado");Check(!AutoConfirmationRunner.Eligible(lib.Describe(ReceivedSummary(501,"2")),SampleCnpj,lib.List()),"não confirma resumo denegado");Check(!AutoConfirmationRunner.Eligible(lib.Describe(ReceivedSummary(500)),SampleCnpj,lib.List()),"XML completo dispensa confirmação para download");
   var scienceHistory=new ScienceStore(Path.Combine(root,"confirm-old-science"));scienceHistory.Enable(SampleCnpj,1,true);q=queues.Load(SampleCnpj,1);q.ScienceForDownload=true;queues.Save(SampleCnpj,1,q);var noScience=new ScienceFake();var scienceRunner=new AutoScienceRunner(states,scienceHistory,queues,lib,noScience,null);Check(scienceRunner.RunForQueue(35,CancellationToken.None)==0&&noScience.Sent==0,"modo de confirmação não envia ciência da fila em paralelo");
   TestConfirmationRecovery(root);TestConfirmationBatch(root);TestConfirmationFirstQuery(root);
  }
  static KeyQueue ConfirmationQueue(params int[] numbers){var q=new KeyQueue{Uf=35,AutoContinue=true,DownloadAll=true,ConfirmForDownload=true,ConfirmationConsent=DateTime.UtcNow};q.AddUserKeys(numbers.Select(ReceivedKey));foreach(var job in q.Jobs){job.Attempts=1;job.Code="138";}return q;}
  static void TestConfirmationRecovery(string root){
   var lib=new XmlLibrary(Path.Combine(root,"confirm-recover-lib"),SampleCnpj,1);lib.Store(ReceivedSummary(510),"1");var states=new StateStore(Path.Combine(root,"confirm-recover-state"));var queues=new KeyQueueStore(Path.Combine(root,"confirm-recover-q"));queues.Save(SampleCnpj,1,ConfirmationQueue(510));var history=new ConfirmationStore(Path.Combine(root,"confirm-recover-history"));var fake=new ConfirmationFake{Fail=true};var runner=new AutoConfirmationRunner(states,history,queues,lib,fake,null);Reject(()=>runner.Run(CancellationToken.None),"resposta perdida da confirmação preserva resultado incerto");Check(history.Load(SampleCnpj,1).Records.Single().Status=="Incerta"&&!queues.Load(SampleCnpj,1).ConfirmForDownload&&queues.Load(SampleCnpj,1).AutoContinue,"erro de confirmação pausa somente novos eventos e preserva downloads");var q=queues.Load(SampleCnpj,1);q.ConfirmForDownload=true;queues.Save(SampleCnpj,1,q);runner.Run(CancellationToken.None);Check(fake.Sent==1&&!queues.Load(SampleCnpj,1).ConfirmForDownload,"reinício após envio incerto não repete confirmação");
   var recoverHistory=new ConfirmationStore(Path.Combine(root,"confirm-queued-history"));var recoverQueues=new KeyQueueStore(Path.Combine(root,"confirm-queued-q"));recoverQueues.Save(SampleCnpj,1,ConfirmationQueue(510));var saved=new ScienceState();saved.Records.Add(new ScienceRecord{Key=ReceivedKey(510),Status="Registrada",Code="135",Protocol="123",At=DateTime.UtcNow});recoverHistory.Save(SampleCnpj,1,saved);var noCall=new ConfirmationFake();var recoverRunner=new AutoConfirmationRunner(states,recoverHistory,recoverQueues,lib,noCall,null);recoverRunner.Run(CancellationToken.None);Check(noCall.Sent==0&&recoverHistory.Load(SampleCnpj,1).Records.Single().Queued&&recoverQueues.Load(SampleCnpj,1).Jobs[0].ConfirmationCode=="135","recupera agendamento após falha sem reenviar confirmação aceita");
   var invalidHistory=new ConfirmationStore(Path.Combine(root,"confirm-invalid-history"));var invalidQueues=new KeyQueueStore(Path.Combine(root,"confirm-invalid-q"));invalidQueues.Save(SampleCnpj,1,ConfirmationQueue(510));var invalidFake=new ConfirmationFake();invalidFake.Replies.Enqueue(ScienceReply(ReceivedKey(511),type:"210200"));Reject(()=>new AutoConfirmationRunner(states,invalidHistory,invalidQueues,lib,invalidFake,null).Run(CancellationToken.None),"retorno incompatível pausa confirmação");Check(invalidHistory.Load(SampleCnpj,1).Records.Single().Status=="Incerta"&&File.Exists(invalidHistory.Load(SampleCnpj,1).Records.Single().ResponsePath),"preserva resposta incompatível sem registrar confirmação aceita");
   var knownLib=new XmlLibrary(Path.Combine(root,"confirm-known-lib"),SampleCnpj,1);knownLib.Store(ReceivedSummary(512),"1");knownLib.Store(ManifestationEvent(512,"210200"),"2");var knownQueues=new KeyQueueStore(Path.Combine(root,"confirm-known-q"));knownQueues.Save(SampleCnpj,1,ConfirmationQueue(512));var knownHistory=new ConfirmationStore(Path.Combine(root,"confirm-known-history"));var knownFake=new ConfirmationFake();new AutoConfirmationRunner(states,knownHistory,knownQueues,knownLib,knownFake,null).Run(CancellationToken.None);Check(knownFake.Sent==0&&knownHistory.Load(SampleCnpj,1).Records.Single().Registered,"aproveita confirmação já registrada no evento distribuído");
   var lockedHistory=new ConfirmationStore(Path.Combine(root,"confirm-locked-history"));var lockedQueues=new KeyQueueStore(Path.Combine(root,"confirm-locked-q"));lockedQueues.Save(SampleCnpj,1,ConfirmationQueue(510));var lockedFake=new ConfirmationFake();using(states.Lock(SampleCnpj,1))Reject(()=>new AutoConfirmationRunner(states,lockedHistory,lockedQueues,lib,lockedFake,null).Run(CancellationToken.None),"impede confirmação concorrente em outra janela");Check(lockedFake.Sent==0&&lockedHistory.Load(SampleCnpj,1).Records.Count==0,"lock indisponível não cria tentativa fiscal inexistente");
   using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();var cancelHistory=new ConfirmationStore(Path.Combine(root,"confirm-cancel-history"));Reject(()=>new AutoConfirmationRunner(states,cancelHistory,lockedQueues,lib,lockedFake,null).Run(cancelled.Token),"cancelamento antes do envio de confirmação");Check(lockedFake.Sent==0&&cancelHistory.Load(SampleCnpj,1).Records.Count==0,"cancelamento não transmite nem cria protocolo");}
  }
  static void TestConfirmationBatch(string root){
   var lib=new XmlLibrary(Path.Combine(root,"confirm-batch-lib"),SampleCnpj,1);for(int i=600;i<621;i++)lib.Store(ReceivedSummary(i),i.ToString());var states=new StateStore(Path.Combine(root,"confirm-batch-state"));var queues=new KeyQueueStore(Path.Combine(root,"confirm-batch-q"));queues.Save(SampleCnpj,1,ConfirmationQueue(Enumerable.Range(600,21).ToArray()));var history=new ConfirmationStore(Path.Combine(root,"confirm-batch-history"));var fake=new ConfirmationFake();DateTime tick=DateTime.UtcNow;var runner=new AutoConfirmationRunner(states,history,queues,lib,fake,null,()=>tick);Check(runner.Run(CancellationToken.None)==20&&fake.Sent==20,"confirma até vinte eventos por janela de cinco minutos");Check(!runner.HasPendingWork()&&runner.Run(CancellationToken.None)==0&&fake.Sent==20,"limite de confirmação é persistente");tick=tick.AddMinutes(6);Check(runner.Run(CancellationToken.None)==1&&fake.Sent==21,"retoma confirmação das chaves restantes sem repetir primeiras");
   var rejectLib=new XmlLibrary(Path.Combine(root,"confirm-reject-lib"),SampleCnpj,1);rejectLib.Store(ReceivedSummary(630),"1");rejectLib.Store(ReceivedSummary(631),"2");var rejectQueues=new KeyQueueStore(Path.Combine(root,"confirm-reject-q"));rejectQueues.Save(SampleCnpj,1,ConfirmationQueue(630,631));var rejectHistory=new ConfirmationStore(Path.Combine(root,"confirm-reject-history"));var rejectFake=new ConfirmationFake();rejectFake.Replies.Enqueue(ScienceReply(ReceivedKey(630),code:"596",type:"210200"));new AutoConfirmationRunner(states,rejectHistory,rejectQueues,rejectLib,rejectFake,null).Run(CancellationToken.None);Check(rejectFake.Sent==2&&rejectHistory.Load(SampleCnpj,1).Records.Count(r=>r.Registered)==1&&rejectHistory.Load(SampleCnpj,1).Records.Single(r=>r.Code=="596").Status=="Rejeitada","confirmação fora do prazo não vira sucesso nem impede outra nota");
   var certQueues=new KeyQueueStore(Path.Combine(root,"confirm-cert-q"));certQueues.Save(SampleCnpj,1,ConfirmationQueue(630,631));var certHistory=new ConfirmationStore(Path.Combine(root,"confirm-cert-history"));var certFake=new ConfirmationFake();certFake.Replies.Enqueue(ScienceReply(ReceivedKey(630),code:"280",type:"210200"));new AutoConfirmationRunner(states,certHistory,certQueues,rejectLib,certFake,null).Run(CancellationToken.None);Check(certFake.Sent==1&&!certQueues.Load(SampleCnpj,1).ConfirmForDownload&&certQueues.Load(SampleCnpj,1).AutoContinue,"erro de certificado pausa confirmações e preserva a fila de XMLs");
   var legacyQueues=new KeyQueueStore(Path.Combine(root,"confirm-legacy-q"));var legacy=new KeyQueue{Uf=35};legacy.Add(new[]{ReceivedKey(650)});legacyQueues.Save(SampleCnpj,1,legacy);Check(!legacyQueues.Load(SampleCnpj,1).ConfirmForDownload&&!legacyQueues.Load(SampleCnpj,1).Jobs[0].UserSupplied,"atualização não autoriza confirmação de fila antiga automaticamente");
  }
  static void TestConfirmationSignature(X509Certificate2 certificate){var payload=SefazClient.ConfirmationDocument(SampleCnpj,1,ReceivedKey(700),certificate);Check(payload.GetElementsByTagName("tpEvento",Rules.NfeNs)[0].InnerText=="210200","payload usa evento de confirmação 210200");Check(payload.GetElementsByTagName("descEvento",Rules.NfeNs)[0].InnerText=="Confirmacao da Operacao","descrição da confirmação corresponde ao leiaute");Check(payload.GetElementsByTagName("nSeqEvento",Rules.NfeNs)[0].InnerText=="1"&&((XmlElement)payload.GetElementsByTagName("infEvento",Rules.NfeNs)[0]).GetAttribute("Id")=="ID210200"+ReceivedKey(700)+"01","confirmação usa ID e sequência inicial próprios");var checker=new SignedXml(payload);checker.LoadXml((XmlElement)payload.GetElementsByTagName("Signature",SignedXml.XmlDsigNamespaceUrl)[0]);Check(checker.CheckSignature(certificate,true),"assinatura de confirmação verificável");var soap=new XmlDocument{PreserveWhitespace=true,XmlResolver=null};soap.LoadXml(Encoding.UTF8.GetString(SefazClient.ScienceEnvelope(payload)));var embedded=new SignedXml(soap);embedded.LoadXml((XmlElement)soap.GetElementsByTagName("Signature",SignedXml.XmlDsigNamespaceUrl)[0]);Check(embedded.CheckSignature(certificate,true),"assinatura de confirmação permanece válida no SOAP");}
  static void TestConfirmationFirstQuery(string root){var lib=new XmlLibrary(Path.Combine(root,"confirm-probe-lib"),SampleCnpj,1);lib.Store(ReceivedSummary(720),"1");var states=new StateStore(Path.Combine(root,"confirm-probe-state"));var queues=new KeyQueueStore(Path.Combine(root,"confirm-probe-q"));var history=new ConfirmationStore(Path.Combine(root,"confirm-probe-history"));var q=ConfirmationQueue(720);q.Jobs[0].Attempts=0;q.Jobs[0].Code="";queues.Save(SampleCnpj,1,q);var fake=new ConfirmationFake();var runner=new AutoConfirmationRunner(states,history,queues,lib,fake,null);Check(!runner.HasPendingWork()&&runner.Run(CancellationToken.None)==0&&fake.Sent==0,"primeiro tenta baixar pela chave antes de enviar confirmação");fake.Docs.Enqueue(Response("138","1","1",InvoiceWithProducts(720)));new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);Check(runner.Run(CancellationToken.None)==0&&fake.Sent==0&&queues.Load(SampleCnpj,1).Jobs[0].Status=="Baixada","XML já disponível é baixado sem confirmação desnecessária");
   var reservedLib=new XmlLibrary(Path.Combine(root,"confirm-reserved-lib"),SampleCnpj,1);reservedLib.Store(ReceivedSummary(721),"1");var reservedQueues=new KeyQueueStore(Path.Combine(root,"confirm-reserved-q"));reservedQueues.Save(SampleCnpj,1,ConfirmationQueue(721));var science=new ScienceStore(Path.Combine(root,"confirm-reserved-science"));science.Enable(SampleCnpj,1,true);var noScience=new ScienceFake();Check(new AutoScienceRunner(states,science,reservedQueues,reservedLib,noScience,null).Run(35,CancellationToken.None)==0&&noScience.Sent==0,"ciência global respeita chaves reservadas à confirmação autorizada");
   string xlsx=Path.Combine(root,"confirm-results.xlsx");QueueSpreadsheet.Save(xlsx,new[]{new KeyJob{Key=ReceivedKey(721),Status="Pendente",Code="138",Message="Aguardando XML",ConfirmationCode="135"}});using(var file=File.OpenRead(xlsx))using(var zip=new System.IO.Compression.ZipArchive(file,System.IO.Compression.ZipArchiveMode.Read))using(var stream=zip.GetEntry("xl/worksheets/sheet1.xml").Open()){var x=XDocument.Load(stream);XNamespace n="http://schemas.openxmlformats.org/spreadsheetml/2006/main";Check(x.Descendants(n+"c").Single(c=>(string)c.Attribute("r")=="F2").Descendants(n+"t").Single().Value=="135","planilha separa código da consulta e código da confirmação");}
  }
